\begin{lemma}[Cauchy's inequality]
\label{lem:cauchys-inequality}
\dcref{appB:B.2-a}
\group{Elementary Inequalities}
For all $a,b\in\R$,
\[
(4)\qquad ab\leq\frac{a^2}{2}+\frac{b^2}{2}.
\]
\end{lemma}
\begin{proof}
\sketch Expand $0\leq(a-b)^2=a^2-2ab+b^2$.
\end{proof}

